// <auto-generated> by cs/tools/ts2cs.mjs from src/sim/visitors.ts, then fixed by hand where it says so.
// Other people: traders who come to swap goods, and raiders who come at night.
//
// Traders: from TRADER_FIRST_DAY, every TRADER_EVERY days at TRADER_HOUR, a
// trader waits at the edge of explored ground (as wanderers do) with three
// offers (sim RNG). Trading takes the asked-for goods from anything free on
// the ground and puts the trader's goods down beside them. They leave after
// TRADER_PATIENCE ticks or at nightfall.
//
// Raiders: from RAID_FIRST_DAY, each nightfall may bring a party (RAID_CHANCE).
// They're zombies of kind 'raider' as far as fighting goes (zombies.ts), but
// they open unlocked doors, hit harder, don't infect, and leave at dawn.
// Lock a door (toggleLock) and they have to batter it like anyone else.
#nullable disable warnings
namespace LoonieRoo.Sim;

public static partial class Visitors
{
    static Visitors()
    {
        Time.onClock(() => TRADER_PATIENCE = 4 * Time.TICKS_PER_HOUR);
    }

    public const int TRADER_FIRST_DAY = 3;

    public const int TRADER_EVERY = 3;

    public const int TRADER_HOUR = 12;

    public static double TRADER_PATIENCE = 4 * Time.TICKS_PER_HOUR;

    public const int RAID_FIRST_DAY = 6;

    public const double RAID_CHANCE = 0.3;

    /// <summary>With an enemy settlement out there.</summary>
    public const double HOSTILE_RAID_CHANCE = 0.5;

    public const int RAIDER_HEALTH = 250;

    public const int RAIDER_DAMAGE = 50;

    public static readonly List<Offer> OFFERS = [new() { give = "weapon", giveCount = 1, want = "food", wantCount = 4 }, new() { give = "medicine", giveCount = 1, want = "wood", wantCount = 4 }, new() { give = "food", giveCount = 5, want = "wood", wantCount = 3 }, new() { give = "bandage", giveCount = 2, want = "food", wantCount = 3 }, new() { give = "wood", giveCount = 5, want = "food", wantCount = 4 }, new() { give = "meal", giveCount = 3, want = "wood", wantCount = 2 }, new() { give = "cloth", giveCount = 3, want = "food", wantCount = 3 }, new() { give = "coat", giveCount = 1, want = "food", wantCount = 4 }, new() { give = "gun", giveCount = 1, want = "food", wantCount = 6 }, new() { give = "ammo", giveCount = 2, want = "wood", wantCount = 3 }];

    public static void updateVisitors(SimState state)
    {
        foreach (var t in Js.Iter((state.traders).ToList()))
        {
            if (Js.T((state.tick >= t.leavesTick) || Js.T(Time.isNight(state.tick))))
            {
                state.traders.splice(state.traders.indexOf(t), 1);
                var home = Settlements.getSettlement(state, t.from);
                if (Js.T(home) && !Js.T(t.traded))
                {
                    Settlements.adjustReputation(state, home, Settlements.SNUB_REP);
                }
                Events.logEvent(state, (Js.T(home) && !Js.T(t.traded)) ? $"The trader went back to {Js.Str(home.name)} empty-handed (they won't forget it)" : "The trader packed up and left");
            }
        }
        var day = Time.dayOf(state.tick);
        if (((day >= TRADER_FIRST_DAY) && (((day - TRADER_FIRST_DAY) % TRADER_EVERY) == 0)) && (Time.tickOfDay(state.tick) == (TRADER_HOUR * Time.TICKS_PER_HOUR)))
        {
            arrive(state);
        }
        var enemy = state.settlements.find(Settlements.isHostile);
        if ((Js.T((day >= RAID_FIRST_DAY) && Js.T(Zombies.nightFallsNow(state.tick)))) && (Rng.random(state) < ((Js.T(enemy) ? HOSTILE_RAID_CHANCE : RAID_CHANCE) * Director.threatScale(state))))
        {
            raid(state, day, enemy?.name);
        }
    }

    public static void arrive(SimState state)
    {
        var spot = Wanderers.frontierSpot(state, new JsSet<string>()) ?? state.survivors[Js.Idx(0)]?.pos;
        if (!Js.T(spot))
        {
            return;
        }
        List<Offer> offers = [];
        List<Offer> left = (OFFERS).ToList();
        for (var i = 0; i < 3; i++)
        {
            var o = Rng.pick(state, left);
            left.splice(left.indexOf(o), 1);
            offers.push(Js.CopyAs<Offer>(o));
        }
        var from = Settlements.traderFrom(state);
        state.traders.push(new() { id = $"t{Js.Str(state.nextId++)}", x = Js.I(spot.x), y = Js.I(spot.y), leavesTick = state.tick + TRADER_PATIENCE, offers = offers, from = from?.id ?? null, traded = false });
        Events.logEvent(state, $"A trader{Js.Str(Js.T(from) ? $" from {Js.Str(from.name)}" : "")} is waiting at ({Js.Str(spot.x)}, {Js.Str(spot.y)})");
    }

    /// <summary>Swaps goods. Returns an error message, or null when done.</summary>
    public static string? trade(SimState state, string traderId, double offer)
    {
        var t = state.traders.find((x) => x.id == traderId);
        var o = t?.offers[Js.Idx(offer)];
        if (!Js.T(t) || !Js.T(o))
        {
            return "no such offer";
        }
        var free = state.items.filter((i) => ((i.kind == o.want) && (i.pos != null)) && (i.reservedBy == null));
        if (free.length < o.wantCount)
        {
            return $"not enough {Js.Str(o.want)} (need {Js.Str(o.wantCount)}, have {Js.Str(free.length)} free)";
        }
        foreach (var item in Js.Iter(free.slice(0, o.wantCount)))
        {
            state.items.splice(state.items.indexOf(item), 1);
        }
        for (var n = 0; n < o.giveCount; n++)
        {
            Items.spawnItem(state, o.give, t.x, t.y);
        }
        t.traded = true;
        var home = Settlements.getSettlement(state, t.from);
        if (Js.T(home))
        {
            Settlements.adjustReputation(state, home, Settlements.TRADE_REP);
        }
        Events.logEvent(state, $"Traded {Js.Str(o.wantCount)} {Js.Str(o.want)} for {Js.Str(o.giveCount)} {Js.Str(o.give)}");
        return null;
    }

    public static void raid(SimState state, double day, string? from = default)
    {
        var spot = Wanderers.frontierSpot(state, new JsSet<string>()) ?? state.survivors[Js.Idx(0)]?.pos;
        if (!Js.T(spot))
        {
            return;
        }
        var size = 2 + JsMath.floor(((double)(day) / (6)));
        for (var n = 0; n < size; n++)
        {
            Point p = new Point { x = Js.I(spot.x + (n % 2)), y = Js.I(spot.y + JsMath.floor(((double)(n) / (2)))) };
            var at = (Grids.getTile(state.grid, p.x, p.y) == "floor") ? p : spot;
            Zombies.addZombie(state, at.x, at.y, RAIDER_HEALTH, "raider");
        }
        Events.logEvent(state, $"Raiders{Js.Str(Js.T(from) ? $" from {Js.Str(from)}" : "")}! {Js.Str(size)} of them, near ({Js.Str(spot.x)}, {Js.Str(spot.y)}). Locked doors will slow them.");
    }
}
